#!/usr/bin/env bash
set -euo pipefail
GSZ=/opt/gsz
A="$GSZ/views/about.ejs"; R="$GSZ/views/resellers.ejs"; T="$GSZ/lib/trialpoll.js"
TS=$(date +%Y%m%d-%H%M%S)
echo "==> step171: About editable + drop 'real people on WhatsApp' copy + trial creds on WhatsApp"
for F in "$A" "$R" "$T"; do cp "$F" "$F.bak-step171-$TS"; done
echo "    backups: *.bak-step171-$TS"
restore(){ echo "!! restoring"; for F in "$A" "$R" "$T"; do cp "$F.bak-step171-$TS" "$F" 2>/dev/null||true; done; }
trap 'restore' ERR
PATCHER=$(mktemp /tmp/patch_step171.XXXXXX.js)
echo "" | base64 -d > "$PATCHER"
echo "==> applying file patches"; NODE_PATH="$GSZ/node_modules" node "$PATCHER" "$GSZ"
echo "==> validating"
NODE_PATH="$GSZ/node_modules" node --check "$T" && echo "    trialpoll.js ok"
for V in "$A" "$R"; do NODE_PATH="$GSZ/node_modules" node -e "const ejs=require('ejs'),fs=require('fs');ejs.compile(fs.readFileSync('$V','utf8'),{filename:'$V'});console.log('    ejs ok: $V')"; done
echo "==> DB: add {{credentials}} to whatsapp.trial_ready"
DBJS=$(mktemp /tmp/db_step171.XXXXXX.js)
echo "" | base64 -d > "$DBJS"
( cd "$GSZ" && NODE_PATH="$GSZ/node_modules" GSZ_ENV="$GSZ/.env" node "$DBJS" )
echo "==> restarting"; pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz
CODE=000; for i in $(seq 1 25); do sleep 1; CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/about || echo 000); [ "$CODE" = "200" ] && break; done
[ "$CODE" = "200" ] || { echo "    /about $CODE"; false; }
echo "    /about 200: OK (after ${i}s)"
rm -f "$PATCHER" "$DBJS"; trap - ERR
echo ""
echo "==> step171 OK  About page intro is now editable from settings.about_html; removed the 'real people on WhatsApp' copy on About + Resellers; trial WhatsApp message now includes the login credentials. Admin editor field for About comes next."
